// Recorded voices: lines rendered offline (Kokoro + DSP from assets/audio/voice/lines.csv) play from assets/audio/voice/<id>.ogg when
// index.json lists the id (the line's slug); anything missing, or undecodable, falls back to speech synthesis. All listed files preload
// once audio is unlocked, so the first play of a line is never late.
const voiceFiles70={ids:null,buf:new Map(),started:false,src:null,until:-9};
const voiceSlug70=s=>s.toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/^_+|_+$/g,'').slice(0,64);
function preloadVoices70(){const v=voiceFiles70;if(v.started||!audio)return;v.started=true;
 fetch('assets/audio/voice/index.json',{credentials:'same-origin'}).then(r=>r.ok?r.json():[]).then(a=>{v.ids=new Set(Array.isArray(a)?a:[]);
  for(const id of v.ids)fetch('assets/audio/voice/'+id+'.ogg',{credentials:'same-origin'}).then(r=>{if(!r.ok)throw Error(r.status);return r.arrayBuffer();}).then(x=>audio.decodeAudioData(x)).then(b=>v.buf.set(id,b)).catch(()=>{});}).catch(()=>{v.ids=new Set();});}
function playVoice70(line,prio){const v=voiceFiles70,b=v.buf.get(voiceSlug70(line));if(!b||!audio||!audioMix9)return false;if(time<v.until){if(!prio)return false;try{v.src.stop();}catch(e){}}
 try{if(voice65.ok&&speechSynthesis.speaking)speechSynthesis.cancel();}catch(e){}
 const s=audio.createBufferSource(),g=audio.createGain();g.gain.value=1.1;s.buffer=b;s.connect(g);g.connect(audioMix9);s.start();v.src=s;v.until=time+b.duration;return true;}
function announce65(line,prio=false){if(!SANDBOX25||!audioAllowed9())return false;if(line===voice65.last&&time-voice65.at<4)return false;
 preloadVoices70();if(playVoice70(line,prio)){voice65.last=line;voice65.at=time;voice65.lines++;return true;}if(!voice65.ok||time<voiceFiles70.until&&!prio)return false;
